TypeScript example (consumer):

const invocation = client.incrementalInvocation({ model: 'rwd-compact-1', prompt: 'Summarize quarterly metrics' });
for await (const ev of invocation.stream()) {
  if (ev.type === 'structured_chunk') {
    // ev.payload is a well-formed JSON fragment we can parse incrementally
    console.log('structured piece:', ev.payload);
  } else if (ev.type === 'tool_call') {
    // cleanly map to a registered tool handler
    await tools.invoke(ev.toolName, ev.args);
  } else if (ev.type === 'done') {
    break;
  }
}

Python example (consumer):

async for ev in client.incremental_invocation(model='rwd-compact-1', prompt='...').aiter():
  if ev['type'] == 'structured_chunk':
    process_json_fragment(ev['payload'])
  elif ev['type'] == 'tool_call':
    await tools.handle(ev['tool_name'], ev.get('args', {}))

Go example (consumer):

inv := client.IncrementalInvocation(ctx, opts)
for ev := range inv.Events() {
  switch ev.Type {
  case "structured_chunk":
    decoder.Append(ev.Payload)
  case "tool_call":
    go tools.Handle(ev.ToolName, ev.Args) // non-blocking by design
  case "done":
    return
  }
}
